using System.Reflection;
using System.Text;
using CommandLine;
using DotLiquid;
using Unityhubctl.GraphQL.Generator.Visitors;

namespace Unityhubctl.GraphQL.Generator;

[Verb("graphql-services-generate",
    HelpText =
        "Generate metadata in addition to code generated by protobuf generated required by UnityHub")]
// ReSharper disable once ClassNeverInstantiated.Global
// ReSharper disable once InconsistentNaming
public class GraphQLServicesGenerateOptions
{
    [Option("namespace", Required = true, HelpText = "The namespace")]
    public string Namespace { get; set; } = string.Empty;

    [Option("input-schema-files-path", Required = true,
        HelpText = "The list of comma separated GraphQL schema files path")]
    public string InputSchemaFilesPath { get; set; } = string.Empty;

    [Option("visitors", Required = true, HelpText = "Graphql Visitors")]
    public string Visitors { get; set; } = string.Empty;

    [Option("output-file-path", Required = true, HelpText = "Specify the output file path")]
    public string OutputFilePath { get; set; } = string.Empty;

    [Option("output-metadata-file-path", Required = true, HelpText = "Specify the output metadata file path")]
    public string OutputMetadataFilePath { get; set; } = string.Empty;
}

// ReSharper disable once InconsistentNaming
public class GraphQLServicesGenerateHandler(GraphQLServicesGenerateOptions options)
{
    public async Task HandleAsync()
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(options.Namespace);
        ArgumentException.ThrowIfNullOrWhiteSpace(options.InputSchemaFilesPath);
        ArgumentException.ThrowIfNullOrWhiteSpace(options.OutputFilePath);

        var inputSchemaFiles = options.InputSchemaFilesPath.Trim().Split(',')
            .Where(inputSchemaFile => !string.IsNullOrWhiteSpace(inputSchemaFile))
            .Select(inputSchemaFile => inputSchemaFile.Trim())
            .ToList();

        if (inputSchemaFiles.Count == 0)
        {
            throw new ArgumentException("No schema file provided");
        }

        var notFoundFiles = inputSchemaFiles.Where(inputSchemaFile => !File.Exists(inputSchemaFile)).ToList();
        if (notFoundFiles.Count != 0)
        {
            throw new ArgumentException($"Provided Schema files do not exist: {string.Join(Environment.NewLine, ",")}");
        }

        var stringBuilder = new StringBuilder();
        foreach (var filePath in inputSchemaFiles)
        {
            stringBuilder.AppendLine(await File.ReadAllTextAsync(filePath));
            stringBuilder.AppendLine();
        }

        var userDefinedVisitors = options.Visitors.Trim().Split(',')
            .Where(visitor => !string.IsNullOrWhiteSpace(visitor))
            .Select(visitor => visitor.Trim())
            .ToList();
        var visitors = userDefinedVisitors.Select(VisitorFactory.Create);
        var schema = stringBuilder.ToString();
        var generatedSource = GenerateSource(visitors, schema);

        await CreateGeneratedSourceAsync(generatedSource);
        await CreateGeneratedMetadataAsync(schema);
    }

    private static string GenerateSource(
        IEnumerable<GeneratableTypeVisitor> visitors,
        string schema)
    {
        var generatableTypeProvider = new GeneratableTypeProvider(visitors);
        var generatableTypes = generatableTypeProvider.FromSchemaText(schema);
        var generatedTypes = generatableTypes.OrderBy(x => x.GraphName).Select(type => type.ToString())!;

        return string.Join(Environment.NewLine, generatedTypes);
    }

    private async Task CreateGeneratedSourceAsync(string generatedSource)
    {
        await using var stream = Assembly.GetExecutingAssembly()
            .GetManifestResourceStream("Unityhubctl.GraphQL.Generator.Resources.GraphQL.liquid");
        ArgumentNullException.ThrowIfNull(stream);

        using var streamReader = new StreamReader(stream);
        var template = Template.Parse(await streamReader.ReadToEndAsync());
        var assembly = Assembly.GetExecutingAssembly().GetName();

        var renderedContent = template.Render(Hash.FromAnonymousObject(new
        {
            tool = assembly.Name,
            version = assembly.Version?.ToString(),
            @namespace = options.Namespace,
            generated_source = generatedSource
        }));

        await File.WriteAllTextAsync(options.OutputFilePath, renderedContent);
    }

    private async Task CreateGeneratedMetadataAsync(string schema)
    {
        await using var stream = Assembly.GetExecutingAssembly()
            .GetManifestResourceStream("Unityhubctl.GraphQL.Generator.Resources.GraphQLMetadata.liquid");
        ArgumentNullException.ThrowIfNull(stream);

        using var streamReader = new StreamReader(stream);
        var template = Template.Parse(await streamReader.ReadToEndAsync());
        var assembly = Assembly.GetExecutingAssembly().GetName();

        var renderedContent = template.Render(Hash.FromAnonymousObject(new
        {
            tool = assembly.Name,
            version = assembly.Version?.ToString(),
            @namespace = options.Namespace,
            schema = schema
                .Replace("\"", "\\\"")
                .Trim()
        }));

        await File.WriteAllTextAsync(options.OutputMetadataFilePath, renderedContent);
    }
}
